import { z } from "zod";

// ---------------------------------------------------------------------------
// Vocabularies
// ---------------------------------------------------------------------------

export const SOURCES = ["stated", "inferred"] as const;
export const COMPANIONS = [
  "solo",
  "partner",
  "friends",
  "family-with-kids",
  "family-adults",
  "group-tour",
] as const;
export const BUDGET_TIERS = ["budget", "midRange", "luxury"] as const;
export const PACES = ["relaxed", "balanced", "packed"] as const;
export const CLIMATES = ["hot", "warm", "mild", "cold"] as const;
export const TRIP_LENGTHS = ["weekend", "1-week", "2-weeks", "extended"] as const;
export const ACCOMMODATIONS = [
  "hostel",
  "budget-hotel",
  "boutique",
  "luxury-hotel",
  "rental",
  "resort",
  "camping",
] as const;
export const PLACE_STATUSES = ["visited", "wishlist"] as const;
export const SENTIMENTS = ["loved", "liked", "neutral", "disliked"] as const;

// ---------------------------------------------------------------------------
// Primitive schemas
// ---------------------------------------------------------------------------

export const sourceSchema = z.enum(SOURCES);
export const monthSchema = z.number().int().min(1).max(12);
export const companionSchema = z.enum(COMPANIONS);
export const budgetTierSchema = z.enum(BUDGET_TIERS);
export const paceSchema = z.enum(PACES);
export const climateSchema = z.enum(CLIMATES);
export const tripLengthSchema = z.enum(TRIP_LENGTHS);
export const accommodationSchema = z.enum(ACCOMMODATIONS);
export const textValueSchema = z.string().min(1).max(120);
export const passportCodeSchema = z
  .string()
  .regex(/^[A-Z]{2}$/, "Use an ISO 3166-1 alpha-2 country code, e.g. US");
export const homeBaseSchema = z.object({
  city: textValueSchema.nullable(),
  country: textValueSchema,
});

/** A list entry. `null` list = not asked yet; `[]` = asked, none. */
function item<T extends z.ZodType>(value: T) {
  return z.object({ id: z.string().min(1), value, source: sourceSchema });
}
function list<T extends z.ZodType>(value: T) {
  return z.array(item(value)).nullable();
}
/** A single-value field. `null` = not asked yet. */
function field<T extends z.ZodType>(value: T) {
  return z.object({ value, source: sourceSchema }).nullable();
}

// ---------------------------------------------------------------------------
// Profile
// ---------------------------------------------------------------------------

export const placeSchema = z.object({
  id: z.string().min(1),
  name: textValueSchema,
  destinationId: z.string().nullable(),
  status: z.enum(PLACE_STATUSES),
  sentiment: z.enum(SENTIMENTS).nullable(),
  months: z.array(monthSchema).nullable(),
  year: z.number().int().min(1900).max(2100).nullable(),
  highlights: z.array(textValueSchema),
  lowlights: z.array(textValueSchema),
  source: sourceSchema,
});

export const rejectionSchema = z.object({
  path: z.string(),
  /** Normalized (lowercased) value the user rejected. */
  value: z.string(),
});

export const profileSchema = z.object({
  schemaVersion: z.literal(1),
  updatedAt: z.string(),
  /** Hard constraints: only ever `stated`. */
  traveler: z.object({
    homeBase: field(homeBaseSchema),
    passports: list(passportCodeSchema),
    dietaryRestrictions: list(textValueSchema),
    accessibilityNeeds: list(textValueSchema),
  }),
  /** Soft preferences: may be `inferred`. */
  preferences: z.object({
    companions: list(companionSchema),
    budgetTier: field(budgetTierSchema),
    pace: field(paceSchema),
    travelMonths: field(z.array(monthSchema).min(1)),
    interests: list(textValueSchema),
    avoid: list(textValueSchema),
    dietaryPreferences: list(textValueSchema),
    climate: list(climateSchema),
    tripLength: field(tripLengthSchema),
    accommodation: list(accommodationSchema),
  }),
  places: z.array(placeSchema),
  rejected: z.array(rejectionSchema),
});

export type UserProfile = z.infer<typeof profileSchema>;
export type Place = z.infer<typeof placeSchema>;
export type Source = z.infer<typeof sourceSchema>;
export type HomeBase = z.infer<typeof homeBaseSchema>;
export type Rejection = z.infer<typeof rejectionSchema>;

export interface ListItem<T = string> {
  id: string;
  value: T;
  source: Source;
}
export interface FieldValue<T = unknown> {
  value: T;
  source: Source;
}

export function createEmptyProfile(now: Date = new Date()): UserProfile {
  return {
    schemaVersion: 1,
    updatedAt: now.toISOString(),
    traveler: {
      homeBase: null,
      passports: null,
      dietaryRestrictions: null,
      accessibilityNeeds: null,
    },
    preferences: {
      companions: null,
      budgetTier: null,
      pace: null,
      travelMonths: null,
      interests: null,
      avoid: null,
      dietaryPreferences: null,
      climate: null,
      tripLength: null,
      accommodation: null,
    },
    places: [],
    rejected: [],
  };
}

import { z } from "zod";
import {
  accommodationSchema,
  budgetTierSchema,
  climateSchema,
  companionSchema,
  homeBaseSchema,
  monthSchema,
  paceSchema,
  passportCodeSchema,
  textValueSchema,
  tripLengthSchema,
  type HomeBase,
} from "./schema";

/** Profile paths that hold a list of items. */
export const LIST_PATHS = [
  "traveler.passports",
  "traveler.dietaryRestrictions",
  "traveler.accessibilityNeeds",
  "preferences.companions",
  "preferences.interests",
  "preferences.avoid",
  "preferences.dietaryPreferences",
  "preferences.climate",
  "preferences.accommodation",
] as const;

/** Profile paths that hold a single value. */
export const FIELD_PATHS = [
  "traveler.homeBase",
  "preferences.budgetTier",
  "preferences.pace",
  "preferences.travelMonths",
  "preferences.tripLength",
] as const;

export type ListPath = (typeof LIST_PATHS)[number];
export type FieldPath = (typeof FIELD_PATHS)[number];
export type ValuePath = ListPath | FieldPath;
export type RejectablePath = ValuePath | "places";

type Section = "traveler" | "preferences";

interface PathMetaBase {
  section: Section;
  key: string;
  label: string;
  /** Hard constraints can never be inferred. */
  hard: boolean;
}

export interface ListPathMeta extends PathMetaBase {
  kind: "list";
  schema: z.ZodType<string>;
  prepare: (raw: string) => string;
}

export interface FieldPathMeta extends PathMetaBase {
  kind: "field";
  schema: z.ZodType;
  prepare: (raw: unknown) => unknown;
  /** Stable, lowercased string form used for rejection matching. */
  serialize: (value: unknown) => string;
}

export const normalizeText = (s: string) => s.trim().replace(/\s+/g, " ");
export const normalizeKey = (s: string) => normalizeText(s).toLowerCase();

const asIs = (s: string) => s.trim();
const upper = (s: string) => s.trim().toUpperCase();

function listMeta(
  path: ListPath,
  label: string,
  hard: boolean,
  schema: z.ZodType<string>,
  prepare: (raw: string) => string = normalizeText,
): ListPathMeta {
  const [section, key] = path.split(".") as [Section, string];
  return { kind: "list", section, key, label, hard, schema, prepare };
}

function fieldMeta(
  path: FieldPath,
  label: string,
  hard: boolean,
  schema: z.ZodType,
  prepare: (raw: unknown) => unknown = (raw) => (typeof raw === "string" ? raw.trim() : raw),
  serialize: (value: unknown) => string = (value) => normalizeKey(String(value)),
): FieldPathMeta {
  const [section, key] = path.split(".") as [Section, string];
  return { kind: "field", section, key, label, hard, schema, prepare, serialize };
}

export const LIST_META: Record<ListPath, ListPathMeta> = {
  "traveler.passports": listMeta("traveler.passports", "Passports", true, passportCodeSchema, upper),
  "traveler.dietaryRestrictions": listMeta(
    "traveler.dietaryRestrictions",
    "Dietary restrictions",
    true,
    textValueSchema,
  ),
  "traveler.accessibilityNeeds": listMeta(
    "traveler.accessibilityNeeds",
    "Accessibility needs",
    true,
    textValueSchema,
  ),
  "preferences.companions": listMeta("preferences.companions", "Companions", false, companionSchema, asIs),
  "preferences.interests": listMeta("preferences.interests", "Interests", false, textValueSchema),
  "preferences.avoid": listMeta("preferences.avoid", "Avoid", false, textValueSchema),
  "preferences.dietaryPreferences": listMeta(
    "preferences.dietaryPreferences",
    "Food preferences",
    false,
    textValueSchema,
  ),
  "preferences.climate": listMeta("preferences.climate", "Climate", false, climateSchema, asIs),
  "preferences.accommodation": listMeta(
    "preferences.accommodation",
    "Accommodation",
    false,
    accommodationSchema,
    asIs,
  ),
};

export const FIELD_META: Record<FieldPath, FieldPathMeta> = {
  "traveler.homeBase": fieldMeta(
    "traveler.homeBase",
    "Home base",
    true,
    homeBaseSchema,
    (raw) => {
      if (raw && typeof raw === "object" && "country" in raw) {
        const hb = raw as { city?: unknown; country: unknown };
        return {
          city: typeof hb.city === "string" && hb.city.trim() ? normalizeText(hb.city) : null,
          country: typeof hb.country === "string" ? normalizeText(hb.country) : hb.country,
        };
      }
      return raw;
    },
    (value) => {
      const hb = value as HomeBase;
      return normalizeKey(`${hb.city ?? ""}|${hb.country}`);
    },
  ),
  "preferences.budgetTier": fieldMeta("preferences.budgetTier", "Budget", false, budgetTierSchema),
  "preferences.pace": fieldMeta("preferences.pace", "Pace", false, paceSchema),
  "preferences.travelMonths": fieldMeta(
    "preferences.travelMonths",
    "Travel months",
    false,
    z.array(monthSchema).min(1),
    (raw) => (Array.isArray(raw) ? [...new Set(raw)].sort((a, b) => a - b) : raw),
    (value) => (value as number[]).join(","),
  ),
  "preferences.tripLength": fieldMeta("preferences.tripLength", "Trip length", false, tripLengthSchema),
};

export function isListPath(path: string): path is ListPath {
  return (LIST_PATHS as readonly string[]).includes(path);
}

export function isFieldPath(path: string): path is FieldPath {
  return (FIELD_PATHS as readonly string[]).includes(path);
}

import { z } from "zod";
import { FIELD_PATHS, LIST_PATHS } from "./paths";
import { homeBaseSchema, monthSchema, PLACE_STATUSES, SENTIMENTS, sourceSchema } from "./schema";

const listPathSchema = z.enum(LIST_PATHS).describe("A profile path that holds a list.");
const fieldPathSchema = z.enum(FIELD_PATHS).describe("A profile path that holds a single value.");
const valuePathSchema = z.enum([...LIST_PATHS, ...FIELD_PATHS]);

const itemRef = {
  id: z.string().optional().describe("Item id from the current profile."),
  value: z.string().optional().describe("Item value (case-insensitive). Used when id is not given."),
};

export const setOpSchema = z
  .object({
    op: z.literal("set"),
    path: fieldPathSchema,
    value: z
      .union([z.string(), z.array(z.number().int()), homeBaseSchema])
      .describe(
        "homeBase: {city, country}; travelMonths: array of month numbers 1-12; others: one allowed string value.",
      ),
    source: sourceSchema,
  })
  .describe("Set a single-value field.");

export const addOpSchema = z
  .object({
    op: z.literal("add"),
    path: listPathSchema,
    value: z.string(),
    source: sourceSchema,
  })
  .describe("Add an item to a list. Duplicates are merged.");

export const removeOpSchema = z
  .object({ op: z.literal("remove"), path: listPathSchema, ...itemRef })
  .describe("Remove an item from a list.");

export const markNoneOpSchema = z
  .object({ op: z.literal("markNone"), path: listPathSchema })
  .describe("The user said they have none (e.g. no dietary restrictions). Sets the list to empty.");

export const clearOpSchema = z
  .object({ op: z.literal("clear"), path: valuePathSchema })
  .describe("Reset a field or list to 'not asked yet'.");

export const confirmOpSchema = z
  .object({ op: z.literal("confirm"), path: valuePathSchema, ...itemRef })
  .describe("The user confirmed an inferred value; marks it as stated.");

export const placeInputSchema = z.object({
  id: z.string().optional().describe("Existing place id, when updating."),
  name: z.string().min(1).describe("Place name as the user said it."),
  destinationId: z.string().nullable().optional().describe("id from getDestinationInfo, if it matched."),
  status: z.enum(PLACE_STATUSES).optional().describe("Required when adding a new place."),
  sentiment: z.enum(SENTIMENTS).nullable().optional(),
  months: z.array(monthSchema).nullable().optional(),
  year: z.number().int().nullable().optional(),
  highlights: z.array(z.string()).optional().describe("Things they did or loved there."),
  lowlights: z.array(z.string()).optional().describe("Things they disliked there."),
  source: sourceSchema.optional(),
});
export type PlaceInput = z.infer<typeof placeInputSchema>;

export const upsertPlaceOpSchema = z
  .object({ op: z.literal("upsertPlace"), place: placeInputSchema })
  .describe("Add a place, or update one matched by id or name.");

export const removePlaceOpSchema = z
  .object({ op: z.literal("removePlace"), id: z.string().optional(), name: z.string().optional() })
  .describe("Remove a place by id or name.");

/** UI-only: the user rejected an item. Removes it and remembers the rejection. */
export const rejectOpSchema = z.object({
  op: z.literal("reject"),
  path: z.enum([...LIST_PATHS, ...FIELD_PATHS, "places"]),
  id: z.string().optional(),
});

const agentOpMembers = [
  setOpSchema,
  addOpSchema,
  removeOpSchema,
  markNoneOpSchema,
  clearOpSchema,
  confirmOpSchema,
  upsertPlaceOpSchema,
  removePlaceOpSchema,
] as const;

/** Ops the LLM may send through the updateProfile tool. */
export const agentOpSchema = z.discriminatedUnion("op", [...agentOpMembers]);

/** Every op the reducer understands. */
export const profileOpSchema = z.discriminatedUnion("op", [...agentOpMembers, rejectOpSchema]);

/** Arguments of the updateProfile tool. */
export const updateProfileArgsSchema = z.object({
  ops: z.array(agentOpSchema).min(1).max(20),
});

/** Body of POST /api/profile. */
export const uiProfileRequestSchema = z.object({
  ops: z.array(rejectOpSchema).min(1).max(20),
});

export type AgentOp = z.infer<typeof agentOpSchema>;
export type RejectOp = z.infer<typeof rejectOpSchema>;
export type ProfileOp = z.infer<typeof profileOpSchema>;

import type { PlaceInput, ProfileOp } from "./ops";
import {
  FIELD_META,
  isFieldPath,
  isListPath,
  LIST_META,
  normalizeKey,
  normalizeText,
  type FieldPath,
  type ListPath,
  type RejectablePath,
} from "./paths";
import type { FieldValue, ListItem, Place, Source, UserProfile } from "./schema";

export type OpResult = { ok: true; op: ProfileOp } | { ok: false; op: ProfileOp; error: string };

export interface ApplyResult {
  profile: UserProfile;
  results: OpResult[];
  /** True when at least one op succeeded. */
  changed: boolean;
}

export interface ApplyOptions {
  now?: () => Date;
  newId?: () => string;
}

/** Thrown for an op that can't be applied; its message is returned to the caller (and the LLM). */
class OpError extends Error {}

interface Ctx {
  newId: () => string;
}

/**
 * Applies ops to a copy of the profile. Ops are applied in order and independently:
 * an invalid op is reported in `results` and skipped, the rest still apply.
 * Every handler validates before mutating, so a failed op leaves no partial change.
 */
export function applyOps(
  profile: UserProfile,
  ops: readonly ProfileOp[],
  options: ApplyOptions = {},
): ApplyResult {
  const next = structuredClone(profile);
  const ctx: Ctx = { newId: options.newId ?? (() => crypto.randomUUID()) };

  const results = ops.map((op): OpResult => {
    try {
      applyOp(next, op, ctx);
      return { ok: true, op };
    } catch (err) {
      if (err instanceof OpError) return { ok: false, op, error: err.message };
      throw err;
    }
  });

  const changed = results.some((r) => r.ok);
  if (changed) next.updatedAt = (options.now?.() ?? new Date()).toISOString();
  return { profile: changed ? next : profile, results, changed };
}

function applyOp(p: UserProfile, op: ProfileOp, ctx: Ctx): void {
  switch (op.op) {
    case "add":
      return addItem(p, op.path, op.value, op.source, ctx);
    case "remove":
      return removeItem(p, op.path, op.id, op.value);
    case "markNone":
      return setList(p, op.path, []);
    case "clear":
      return isListPath(op.path) ? setList(p, op.path, null) : setField(p, op.path, null);
    case "set":
      return setFieldValue(p, op.path, op.value, op.source);
    case "confirm":
      return confirm(p, op.path, op.id, op.value);
    case "upsertPlace":
      return upsertPlace(p, op.place, ctx);
    case "removePlace":
      return removePlace(p, op.id, op.name);
    case "reject":
      return reject(p, op.path, op.id);
  }
}

// ---------------------------------------------------------------------------
// Accessors
// ---------------------------------------------------------------------------

function sectionOf(p: UserProfile, section: "traveler" | "preferences"): Record<string, unknown> {
  return p[section] as unknown as Record<string, unknown>;
}

function getList(p: UserProfile, path: ListPath): ListItem[] | null {
  const { section, key } = LIST_META[path];
  return sectionOf(p, section)[key] as ListItem[] | null;
}

function setList(p: UserProfile, path: ListPath, value: ListItem[] | null): void {
  const { section, key } = LIST_META[path];
  sectionOf(p, section)[key] = value;
}

function getField(p: UserProfile, path: FieldPath): FieldValue | null {
  const { section, key } = FIELD_META[path];
  return sectionOf(p, section)[key] as FieldValue | null;
}

function setField(p: UserProfile, path: FieldPath, value: FieldValue | null): void {
  const { section, key } = FIELD_META[path];
  sectionOf(p, section)[key] = value;
}

// ---------------------------------------------------------------------------
// Rejections
// ---------------------------------------------------------------------------

function isRejected(p: UserProfile, path: RejectablePath, key: string): boolean {
  return p.rejected.some((r) => r.path === path && r.value === key);
}

function recordRejection(p: UserProfile, path: RejectablePath, key: string): void {
  if (!isRejected(p, path, key)) p.rejected.push({ path, value: key });
}

function clearRejection(p: UserProfile, path: RejectablePath, key: string): void {
  p.rejected = p.rejected.filter((r) => !(r.path === path && r.value === key));
}

function guardSource(label: string, hard: boolean, source: Source): void {
  if (hard && source === "inferred") {
    throw new OpError(`${label} is a hard constraint and can only be set from what the user states.`);
  }
}

function guardRejected(p: UserProfile, path: RejectablePath, key: string, source: Source, display: string) {
  if (source === "inferred" && isRejected(p, path, key)) {
    throw new OpError(`The user rejected "${display}" for ${path}. Don't add it again unless they state it.`);
  }
  if (source === "stated") clearRejection(p, path, key);
}

// ---------------------------------------------------------------------------
// List ops
// ---------------------------------------------------------------------------

function addItem(p: UserProfile, path: ListPath, raw: string, source: Source, ctx: Ctx): void {
  const meta = LIST_META[path];
  guardSource(meta.label, meta.hard, source);

  const parsed = meta.schema.safeParse(meta.prepare(raw));
  if (!parsed.success) {
    throw new OpError(`Invalid value "${raw}" for ${path}: ${parsed.error.issues[0]?.message}`);
  }
  const value = parsed.data;
  const key = normalizeKey(value);
  guardRejected(p, path, key, source, value);

  const items = getList(p, path) ?? [];
  const existing = items.find((i) => normalizeKey(i.value) === key);
  if (existing) {
    if (source === "stated") existing.source = "stated";
  } else {
    items.push({ id: ctx.newId(), value, source });
  }
  setList(p, path, items);
}

function findItemIndex(items: ListItem[], label: string, id?: string, value?: string): number {
  if (!id && !value) throw new OpError(`Provide an id or value to identify the ${label} item.`);
  const index = id
    ? items.findIndex((i) => i.id === id)
    : items.findIndex((i) => normalizeKey(i.value) === normalizeKey(value!));
  if (index < 0) throw new OpError(`No matching item "${id ?? value}" in ${label}.`);
  return index;
}

function removeItem(p: UserProfile, path: ListPath, id?: string, value?: string): void {
  const meta = LIST_META[path];
  const items = getList(p, path);
  if (!items) throw new OpError(`${meta.label} has no items.`);
  const index = findItemIndex(items, meta.label, id, value);
  setList(p, path, items.filter((_, i) => i !== index));
}

// ---------------------------------------------------------------------------
// Field ops
// ---------------------------------------------------------------------------

function setFieldValue(p: UserProfile, path: FieldPath, raw: unknown, source: Source): void {
  const meta = FIELD_META[path];
  guardSource(meta.label, meta.hard, source);

  const parsed = meta.schema.safeParse(meta.prepare(raw));
  if (!parsed.success) {
    throw new OpError(`Invalid value for ${path}: ${parsed.error.issues[0]?.message}`);
  }
  const key = meta.serialize(parsed.data);
  guardRejected(p, path, key, source, key);
  setField(p, path, { value: parsed.data, source });
}

// ---------------------------------------------------------------------------
// Confirm / reject
// ---------------------------------------------------------------------------

function confirm(p: UserProfile, path: string, id?: string, value?: string): void {
  if (isListPath(path)) {
    const meta = LIST_META[path];
    const items = getList(p, path);
    if (!items) throw new OpError(`${meta.label} has no items.`);
    const item = items[findItemIndex(items, meta.label, id, value)];
    item.source = "stated";
    clearRejection(p, path, normalizeKey(item.value));
    return;
  }
  if (isFieldPath(path)) {
    const current = getField(p, path);
    if (!current) throw new OpError(`${FIELD_META[path].label} is not set.`);
    current.source = "stated";
    return;
  }
  throw new OpError(`Unknown path ${path}.`);
}

function reject(p: UserProfile, path: RejectablePath, id?: string): void {
  if (path === "places") {
    if (!id) throw new OpError("Provide the id of the place to reject.");
    const place = p.places.find((pl) => pl.id === id);
    if (!place) throw new OpError(`No place with id ${id}.`);
    p.places = p.places.filter((pl) => pl.id !== id);
    recordRejection(p, "places", normalizeKey(place.name));
    return;
  }
  if (isListPath(path)) {
    const meta = LIST_META[path];
    const items = getList(p, path);
    if (!items) throw new OpError(`${meta.label} has no items.`);
    if (!id) throw new OpError(`Provide the id of the ${meta.label} item to reject.`);
    const index = findItemIndex(items, meta.label, id);
    recordRejection(p, path, normalizeKey(items[index].value));
    setList(p, path, items.filter((_, i) => i !== index));
    return;
  }
  const meta = FIELD_META[path];
  const current = getField(p, path);
  if (!current) throw new OpError(`${meta.label} is not set.`);
  recordRejection(p, path, meta.serialize(current.value));
  setField(p, path, null);
}

// ---------------------------------------------------------------------------
// Places
// ---------------------------------------------------------------------------

function findPlace(p: UserProfile, id?: string, name?: string): Place | undefined {
  if (id) {
    const byId = p.places.find((pl) => pl.id === id);
    if (byId) return byId;
  }
  if (name) return p.places.find((pl) => normalizeKey(pl.name) === normalizeKey(name));
  return undefined;
}

function mergeTexts(existing: string[], incoming: string[] | undefined): string[] {
  const out = [...existing];
  for (const raw of incoming ?? []) {
    const text = normalizeText(raw);
    if (text && !out.some((e) => normalizeKey(e) === normalizeKey(text))) out.push(text);
  }
  return out;
}

function validMonths(months: number[] | null | undefined): number[] | null | undefined {
  if (months == null) return months;
  return [...new Set(months)].sort((a, b) => a - b);
}

function upsertPlace(p: UserProfile, input: PlaceInput, ctx: Ctx): void {
  const name = normalizeText(input.name);
  if (!name) throw new OpError("Place name is required.");
  const source: Source = input.source ?? "stated";
  const existing = findPlace(p, input.id, name);

  if (existing) {
    if (input.destinationId !== undefined) existing.destinationId = input.destinationId;
    if (input.status !== undefined) existing.status = input.status;
    if (input.sentiment !== undefined) existing.sentiment = input.sentiment;
    if (input.months !== undefined) existing.months = validMonths(input.months) ?? null;
    if (input.year !== undefined) existing.year = input.year;
    existing.highlights = mergeTexts(existing.highlights, input.highlights);
    existing.lowlights = mergeTexts(existing.lowlights, input.lowlights);
    if (source === "stated") existing.source = "stated";
    return;
  }

  if (!input.status) throw new OpError(`Status (visited or wishlist) is required to add "${name}".`);
  guardRejected(p, "places", normalizeKey(name), source, name);
  p.places.push({
    id: ctx.newId(),
    name,
    destinationId: input.destinationId ?? null,
    status: input.status,
    sentiment: input.sentiment ?? null,
    months: validMonths(input.months) ?? null,
    year: input.year ?? null,
    highlights: mergeTexts([], input.highlights),
    lowlights: mergeTexts([], input.lowlights),
    source,
  });
}

function removePlace(p: UserProfile, id?: string, name?: string): void {
  if (!id && !name) throw new OpError("Provide the id or name of the place to remove.");
  const place = findPlace(p, id, name);
  if (!place) throw new OpError(`No place matching "${id ?? name}".`);
  p.places = p.places.filter((pl) => pl.id !== place.id);
}

import type { UserProfile } from "./schema";

export interface Essential {
  key: string;
  label: string;
  isDone: (p: UserProfile) => boolean;
}

/** The 9 essentials, in the order the agent should ask about them. */
export const ESSENTIALS: readonly Essential[] = [
  { key: "homeBase", label: "Home base", isDone: (p) => p.traveler.homeBase !== null },
  { key: "passports", label: "Passports", isDone: (p) => (p.traveler.passports?.length ?? 0) > 0 },
  { key: "companions", label: "Companions", isDone: (p) => (p.preferences.companions?.length ?? 0) > 0 },
  {
    key: "dietaryRestrictions",
    label: "Dietary restrictions",
    isDone: (p) => p.traveler.dietaryRestrictions !== null,
  },
  {
    key: "accessibilityNeeds",
    label: "Accessibility needs",
    isDone: (p) => p.traveler.accessibilityNeeds !== null,
  },
  { key: "travelMonths", label: "Travel months", isDone: (p) => p.preferences.travelMonths !== null },
  { key: "budgetTier", label: "Budget", isDone: (p) => p.preferences.budgetTier !== null },
  { key: "pace", label: "Pace", isDone: (p) => p.preferences.pace !== null },
  { key: "interests", label: "Interests", isDone: (p) => (p.preferences.interests?.length ?? 0) >= 3 },
];

export const MIN_INTERESTS = 3;

export type ProfileStatus = "blank" | "incomplete" | "complete";

export interface Completeness {
  done: number;
  total: number;
  /** Keys of essentials still missing, in ask order. */
  missing: string[];
  status: ProfileStatus;
}

export function getCompleteness(p: UserProfile): Completeness {
  const missing = ESSENTIALS.filter((e) => !e.isDone(p)).map((e) => e.key);
  const total = ESSENTIALS.length;
  const done = total - missing.length;
  return { done, total, missing, status: getStatus(p, missing.length) };
}

function getStatus(p: UserProfile, missingCount: number): ProfileStatus {
  if (missingCount === 0) return "complete";
  return isBlank(p) ? "blank" : "incomplete";
}

/** True when nothing at all has been recorded (rejections don't count). */
export function isBlank(p: UserProfile): boolean {
  const values = [...Object.values(p.traveler), ...Object.values(p.preferences)];
  return values.every((v) => v === null) && p.places.length === 0;
}

