import type { COMPANIONS, PACES } from "@/lib/profile/schema";

export const SUPPORTED_PASSPORTS = ["US", "GB", "CA", "AU", "IN", "DE"] as const;
export type SupportedPassport = (typeof SUPPORTED_PASSPORTS)[number];

/**
 * Shared vocabulary between DestinationInfo.knownFor and profile interests,
 * so the agent can map one onto the other.
 */
export const INTEREST_TAGS = [
  "food",
  "street food",
  "wine",
  "markets",
  "shopping",
  "history",
  "architecture",
  "art",
  "museums",
  "temples",
  "gardens",
  "culture",
  "festivals",
  "nightlife",
  "nature",
  "hiking",
  "beaches",
  "wildlife",
  "adventure",
  "scenic drives",
  "wellness",
  "photography",
] as const;
export type InterestTag = (typeof INTEREST_TAGS)[number];

export type VisaType = "visa-free" | "e-visa" | "visa-on-arrival" | "visa-required";

export interface VisaRule {
  type: VisaType;
  maxStayDays?: number;
  note?: string;
}

export interface DestinationInfo {
  id: string;
  name: string;
  /** ISO 3166-1 alpha-2 */
  country: string;
  countryName: string;
  aliases: string[];
  bestMonths: number[];
  climateSummary: string;
  knownFor: InterestTag[];
  goodFor: (typeof COMPANIONS)[number][];
  pace: (typeof PACES)[number][];
  /** Per person, per day, including lodging. */
  averageDailyCostUSD: { budget: number; midRange: number; luxury: number };
  visa: {
    byPassport: Record<SupportedPassport, VisaRule>;
    /** For passports not in SUPPORTED_PASSPORTS. */
    defaultNote: string;
  };
  cuisine: string[];
  dietaryNotes: string;
  accessibilityNotes: string;
  watchOutFor: string[];
}

import { DESTINATIONS } from "./data";
import type { DestinationInfo } from "./types";

/** Lowercase, strip accents and punctuation, collapse whitespace. */
export function normalizeDestinationName(input: string): string {
  return input
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

const index = new Map<string, DestinationInfo>();
for (const d of DESTINATIONS) {
  for (const n of [d.name, ...d.aliases]) index.set(normalizeDestinationName(n), d);
}

/** Candidate keys for an input: as-is, before a comma, and without a trailing country name. */
function candidates(input: string): string[] {
  const keys = new Set<string>();
  const full = normalizeDestinationName(input);
  if (full) keys.add(full);

  const beforeComma = normalizeDestinationName(input.split(",")[0] ?? "");
  if (beforeComma) keys.add(beforeComma);

  for (const d of DESTINATIONS) {
    const country = normalizeDestinationName(d.countryName);
    for (const key of [...keys]) {
      if (key.endsWith(` ${country}`)) keys.add(key.slice(0, -country.length - 1).trim());
    }
  }
  return [...keys];
}

/**
 * Looks up hardcoded info for a destination. Returns null for anything that
 * isn't one of the known destinations (including country names on their own).
 */
export function getDestinationInfo(name: string): DestinationInfo | null {
  for (const key of candidates(name)) {
    const match = index.get(key);
    if (match) return structuredClone(match);
  }
  return null;
}

/** Display names of all known destinations, for the system prompt. */
export function listDestinationNames(): string[] {
  return DESTINATIONS.map((d) => `${d.name}, ${d.countryName}`);
}

import { describe, expect, it } from "vitest";
import { DESTINATIONS } from "./data";
import { getDestinationInfo, listDestinationNames, normalizeDestinationName } from "./getDestinationInfo";
import { INTEREST_TAGS, SUPPORTED_PASSPORTS } from "./types";

describe("getDestinationInfo", () => {
  it.each([
    ["Kyoto", "kyoto"],
    ["kyoto", "kyoto"],
    ["  KYOTO  ", "kyoto"],
    ["Kyōto", "kyoto"],
    ["Kyoto, Japan", "kyoto"],
    ["kyoto japan", "kyoto"],
    ["Lisboa", "lisbon"],
    ["Marrakesh", "marrakech"],
    ["Reykjavik", "reykjavik"],
    ["Reykjavík, Iceland", "reykjavik"],
    ["cape-town!", "cape-town"],
    ["Capetown", "cape-town"],
    ["Cape Town, South Africa", "cape-town"],
  ])("matches %j", (input, id) => {
    expect(getDestinationInfo(input)?.id).toBe(id);
  });

  it.each(["Bangkok", "Japan", "Tokyo", "", "   ", "Kyoto Prefecture tour"])(
    "returns null for %j",
    (input) => {
      expect(getDestinationInfo(input)).toBeNull();
    },
  );

  it("returns a copy so callers can't mutate the data", () => {
    const a = getDestinationInfo("Kyoto")!;
    a.knownFor.push("nightlife");
    expect(getDestinationInfo("Kyoto")!.knownFor).not.toContain("nightlife");
  });

  it("lists display names", () => {
    expect(listDestinationNames()).toContain("Kyoto, Japan");
    expect(listDestinationNames()).toHaveLength(5);
  });
});

describe("normalizeDestinationName", () => {
  it("strips accents, punctuation and extra spaces", () => {
    expect(normalizeDestinationName("  Reykjavík!!  City ")).toBe("reykjavik city");
  });
});

describe("destination data", () => {
  it("has exactly 5 destinations with unique ids and names", () => {
    expect(DESTINATIONS).toHaveLength(5);
    expect(new Set(DESTINATIONS.map((d) => d.id)).size).toBe(5);
  });

  it("has no alias that collides with another destination", () => {
    const seen = new Map<string, string>();
    for (const d of DESTINATIONS) {
      for (const n of [d.name, ...d.aliases]) {
        const key = normalizeDestinationName(n);
        expect(seen.get(key) ?? d.id).toBe(d.id);
        seen.set(key, d.id);
      }
    }
  });

  it.each(DESTINATIONS.map((d) => [d.id, d] as const))("%s is well-formed", (_id, d) => {
    expect(d.bestMonths.length).toBeGreaterThan(0);
    expect(d.bestMonths.every((m) => Number.isInteger(m) && m >= 1 && m <= 12)).toBe(true);
    for (const tag of d.knownFor) expect(INTEREST_TAGS).toContain(tag);
    for (const p of SUPPORTED_PASSPORTS) expect(d.visa.byPassport[p]).toBeDefined();
    const c = d.averageDailyCostUSD;
    expect(c.budget).toBeLessThan(c.midRange);
    expect(c.midRange).toBeLessThan(c.luxury);
    expect(d.country).toMatch(/^[A-Z]{2}$/);
  });
});

