import { mkdirSync } from "node:fs";
import path from "node:path";
import { DatabaseSync } from "node:sqlite";

export type Db = DatabaseSync;

const SCHEMA = `
CREATE TABLE IF NOT EXISTS profile (
  id         INTEGER PRIMARY KEY CHECK (id = 1),
  json       TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS messages (
  seq        INTEGER PRIMARY KEY AUTOINCREMENT,
  id         TEXT NOT NULL UNIQUE,
  role       TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
  content    TEXT NOT NULL,
  tools      TEXT NOT NULL DEFAULT '[]',
  status     TEXT NOT NULL DEFAULT 'complete' CHECK (status IN ('complete', 'interrupted', 'error')),
  created_at TEXT NOT NULL
);
`;

/** Opens (and creates if needed) a database. Pass ":memory:" in tests. */
export function openDb(file: string): Db {
  if (file !== ":memory:") mkdirSync(path.dirname(file), { recursive: true });
  const db = new DatabaseSync(file);
  if (file !== ":memory:") db.exec("PRAGMA journal_mode = WAL;");
  db.exec(SCHEMA);
  return db;
}

const DEFAULT_PATH = path.join(process.cwd(), "data", "app.db");

// Cached on globalThis so dev-mode hot reloads reuse one connection.
const globalForDb = globalThis as unknown as { __profileBuilderDb?: Db };

/** The app's shared database connection (server only). */
export function getDb(): Db {
  globalForDb.__profileBuilderDb ??= openDb(process.env.DATABASE_PATH ?? DEFAULT_PATH);
  return globalForDb.__profileBuilderDb;
}

/** Runs fn inside a write transaction, rolling back if it throws. */
export function transaction<T>(db: Db, fn: () => T): T {
  db.exec("BEGIN IMMEDIATE");
  try {
    const result = fn();
    db.exec("COMMIT");
    return result;
  } catch (err) {
    db.exec("ROLLBACK");
    throw err;
  }
}

import type { ProfileOp } from "@/lib/profile/ops";
import { applyOps, type ApplyResult } from "@/lib/profile/reducer";
import { createEmptyProfile, profileSchema, type UserProfile } from "@/lib/profile/schema";
import { getDb, transaction, type Db } from "./index";

/**
 * Loads the single user's profile. Returns an empty profile when none is stored,
 * or when the stored JSON is unreadable or fails validation (logged, not thrown).
 */
export function loadProfile(db: Db = getDb()): UserProfile {
  const row = db.prepare("SELECT json FROM profile WHERE id = 1").get() as { json: string } | undefined;
  if (!row) return createEmptyProfile();
  try {
    const parsed = profileSchema.safeParse(JSON.parse(row.json));
    if (parsed.success) return parsed.data;
    console.warn("[profile] stored profile failed validation; starting fresh", parsed.error.issues);
  } catch (err) {
    console.warn("[profile] stored profile is not valid JSON; starting fresh", err);
  }
  return createEmptyProfile();
}

/** Validates and saves the profile. Throws if the profile is invalid (a bug, not user error). */
export function saveProfile(profile: UserProfile, db: Db = getDb()): void {
  const valid = profileSchema.parse(profile);
  db.prepare(
    `INSERT INTO profile (id, json, updated_at) VALUES (1, ?, ?)
     ON CONFLICT(id) DO UPDATE SET json = excluded.json, updated_at = excluded.updated_at`,
  ).run(JSON.stringify(valid), valid.updatedAt);
}

/** Loads, applies ops and saves (only if something changed) in one transaction. */
export function applyProfileOps(ops: readonly ProfileOp[], db: Db = getDb()): ApplyResult {
  return transaction(db, () => {
    const result = applyOps(loadProfile(db), ops);
    if (result.changed) saveProfile(result.profile, db);
    return result;
  });
}

import { z } from "zod";
import { getDb, type Db } from "./index";

export const toolEventSchema = z.object({
  name: z.enum(["getDestinationInfo", "updateProfile"]),
  /** For getDestinationInfo: the place name asked about. */
  arg: z.string().optional(),
  /** For getDestinationInfo: whether the destination was known. */
  found: z.boolean().optional(),
});

export type ToolEvent = z.infer<typeof toolEventSchema>;
export type MessageRole = "user" | "assistant";
export type MessageStatus = "complete" | "interrupted" | "error";

export interface ChatMessage {
  id: string;
  role: MessageRole;
  content: string;
  tools: ToolEvent[];
  status: MessageStatus;
  createdAt: string;
}

export interface NewMessage {
  role: MessageRole;
  content: string;
  tools?: ToolEvent[];
  status?: MessageStatus;
}

interface Row {
  id: string;
  role: MessageRole;
  content: string;
  tools: string;
  status: MessageStatus;
  created_at: string;
}

const COLUMNS = "id, role, content, tools, status, created_at";

function parseTools(json: string): ToolEvent[] {
  try {
    const parsed = z.array(toolEventSchema).safeParse(JSON.parse(json));
    return parsed.success ? parsed.data : [];
  } catch {
    return [];
  }
}

function toMessage(row: Row): ChatMessage {
  return {
    id: row.id,
    role: row.role,
    content: row.content,
    tools: parseTools(row.tools),
    status: row.status,
    createdAt: row.created_at,
  };
}

export function insertMessage(input: NewMessage, db: Db = getDb()): ChatMessage {
  const message: ChatMessage = {
    id: crypto.randomUUID(),
    role: input.role,
    content: input.content,
    tools: input.tools ?? [],
    status: input.status ?? "complete",
    createdAt: new Date().toISOString(),
  };
  db.prepare(`INSERT INTO messages (${COLUMNS}) VALUES (?, ?, ?, ?, ?, ?)`).run(
    message.id,
    message.role,
    message.content,
    JSON.stringify(message.tools),
    message.status,
    message.createdAt,
  );
  return message;
}

/** All messages, oldest first (capped as a safety net). */
export function listMessages(db: Db = getDb(), limit = 500): ChatMessage[] {
  const rows = db.prepare(`SELECT ${COLUMNS} FROM messages ORDER BY seq ASC LIMIT ?`).all(limit) as unknown as Row[];
  return rows.map(toMessage);
}

/** The most recent `count` messages, oldest first. */
export function listRecentMessages(count: number, db: Db = getDb()): ChatMessage[] {
  const rows = db
    .prepare(`SELECT ${COLUMNS} FROM messages ORDER BY seq DESC LIMIT ?`)
    .all(count) as unknown as Row[];
  return rows.reverse().map(toMessage);
}

export function getLastMessage(db: Db = getDb()): ChatMessage | null {
  const row = db.prepare(`SELECT ${COLUMNS} FROM messages ORDER BY seq DESC LIMIT 1`).get() as Row | undefined;
  return row ? toMessage(row) : null;
}

/** Used when retrying: removes the failed assistant reply being replaced. */
export function deleteMessage(id: string, db: Db = getDb()): boolean {
  return db.prepare("DELETE FROM messages WHERE id = ?").run(id).changes > 0;
}

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { openDb, transaction, type Db } from "./index";
import { deleteMessage, getLastMessage, insertMessage, listMessages, listRecentMessages } from "./messageRepo";
import { applyProfileOps, loadProfile, saveProfile } from "./profileRepo";

let db: Db;
beforeEach(() => {
  db = openDb(":memory:");
});
afterEach(() => {
  db.close();
  vi.restoreAllMocks();
});

describe("profileRepo", () => {
  it("returns an empty profile when nothing is stored", () => {
    const p = loadProfile(db);
    expect(p.traveler.homeBase).toBeNull();
    expect(p.places).toEqual([]);
  });

  it("round-trips a saved profile", () => {
    const { profile } = applyProfileOps(
      [{ op: "add", path: "preferences.interests", value: "hiking", source: "stated" }],
      db,
    );
    expect(loadProfile(db)).toEqual(profile);
  });

  it("falls back to an empty profile when stored JSON is corrupt or invalid", () => {
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
    db.prepare("INSERT INTO profile (id, json, updated_at) VALUES (1, ?, ?)").run("{not json", "x");
    expect(loadProfile(db).places).toEqual([]);
    db.prepare("UPDATE profile SET json = ? WHERE id = 1").run(JSON.stringify({ schemaVersion: 99 }));
    expect(loadProfile(db).places).toEqual([]);
    expect(warn).toHaveBeenCalledTimes(2);
  });

  it("refuses to save an invalid profile", () => {
    const bad = { ...loadProfile(db), schemaVersion: 2 } as unknown as Parameters<typeof saveProfile>[0];
    expect(() => saveProfile(bad, db)).toThrow();
  });

  it("only writes when an op changed something, and reports per-op results", () => {
    const r = applyProfileOps([{ op: "remove", path: "preferences.avoid", value: "x" }], db);
    expect(r.changed).toBe(false);
    expect(r.results[0].ok).toBe(false);
    expect(db.prepare("SELECT COUNT(*) AS n FROM profile").get()).toEqual({ n: 0 });
  });
});

describe("messageRepo", () => {
  it("inserts and lists messages oldest first, with tool events", () => {
    insertMessage({ role: "assistant", content: "Hi!" }, db);
    insertMessage({ role: "user", content: "I loved Kyoto" }, db);
    insertMessage(
      {
        role: "assistant",
        content: "Great pick.",
        tools: [{ name: "getDestinationInfo", arg: "Kyoto", found: true }, { name: "updateProfile" }],
      },
      db,
    );
    const all = listMessages(db);
    expect(all.map((m) => m.content)).toEqual(["Hi!", "I loved Kyoto", "Great pick."]);
    expect(all[2].tools).toEqual([{ name: "getDestinationInfo", arg: "Kyoto", found: true }, { name: "updateProfile" }]);
    expect(all[0].status).toBe("complete");
  });

  it("returns the most recent N in chronological order", () => {
    for (let i = 1; i <= 5; i++) insertMessage({ role: i % 2 ? "user" : "assistant", content: `m${i}` }, db);
    expect(listRecentMessages(2, db).map((m) => m.content)).toEqual(["m4", "m5"]);
    expect(getLastMessage(db)?.content).toBe("m5");
  });

  it("stores status and deletes by id", () => {
    const m = insertMessage({ role: "assistant", content: "partial", status: "error" }, db);
    expect(getLastMessage(db)?.status).toBe("error");
    expect(deleteMessage(m.id, db)).toBe(true);
    expect(deleteMessage(m.id, db)).toBe(false);
    expect(getLastMessage(db)).toBeNull();
  });

  it("tolerates malformed tool JSON", () => {
    db.prepare(
      "INSERT INTO messages (id, role, content, tools, status, created_at) VALUES ('x', 'assistant', 'hi', 'oops', 'complete', 't')",
    ).run();
    expect(listMessages(db)[0].tools).toEqual([]);
  });
});

