import type { ServerEvent } from "@/lib/chat/types";

/** Formats one Server-Sent Event frame. */
export function encodeSse<E extends ServerEvent>(event: E["event"], data: E["data"]): string {
  return `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
}

export interface RawSseEvent {
  event: string;
  data: string;
}

/**
 * Incremental SSE parser. Feed it text chunks as they arrive (chunks may split
 * an event anywhere); it calls onEvent once per complete event.
 */
export function createSseParser(onEvent: (e: RawSseEvent) => void) {
  let buffer = "";

  function dispatch(block: string) {
    let event = "message";
    const data: string[] = [];
    for (const line of block.split("\n")) {
      if (!line || line.startsWith(":")) continue;
      const colon = line.indexOf(":");
      const field = colon === -1 ? line : line.slice(0, colon);
      let value = colon === -1 ? "" : line.slice(colon + 1);
      if (value.startsWith(" ")) value = value.slice(1);
      if (field === "event") event = value;
      else if (field === "data") data.push(value);
    }
    if (data.length) onEvent({ event, data: data.join("\n") });
  }

  return {
    push(chunk: string) {
      buffer += chunk.replace(/\r\n?/g, "\n");
      let end: number;
      while ((end = buffer.indexOf("\n\n")) !== -1) {
        dispatch(buffer.slice(0, end));
        buffer = buffer.slice(end + 2);
      }
    },
    /** Dispatches any trailing event without a final blank line. */
    flush() {
      if (buffer.trim()) dispatch(buffer);
      buffer = "";
    },
  };
}

import type { Completeness } from "@/lib/profile/completeness";

/** One question per essential, used to resume an incomplete profile. */
export const ESSENTIAL_QUESTIONS: Record<string, string> = {
  homeBase: "where are you based?",
  passports: "which passport or passports do you travel on?",
  companions: "who do you usually travel with?",
  dietaryRestrictions: "do you have any dietary restrictions or accessibility needs I should keep in mind?",
  accessibilityNeeds: "do you have any accessibility needs I should keep in mind?",
  travelMonths: "what time of year do you like to travel?",
  budgetTier: "what kind of budget do you usually travel on: budget, mid-range or luxury?",
  pace: "do you prefer a relaxed pace, a balanced mix, or packing in as much as possible?",
  interests: "what do you most enjoy doing when you travel?",
};

export const BLANK_OPENING =
  "Hi! I'll build your travel profile through a short conversation. Everything I learn shows up in the ledger on the right, and you can remove anything that's off.\n\nTo start: where are you based, and which passport or passports do you travel on?";

/**
 * The fixed first message shown on page load (no LLM call).
 * - blank profile, no history: welcome + first question
 * - incomplete: welcome back + question for the first missing essential
 * - complete: welcome back + invitation to update
 */
export function buildOpening(completeness: Completeness, hasHistory: boolean): string {
  if (completeness.status === "complete") {
    return "Welcome back! Your travel profile is complete. Tell me if anything has changed, or remove anything that's off in the ledger.";
  }
  if (completeness.status === "blank" && !hasHistory) return BLANK_OPENING;

  const next = completeness.missing[0];
  const question = (next && ESSENTIAL_QUESTIONS[next]) ?? ESSENTIAL_QUESTIONS.homeBase;
  return `Welcome back! Let's pick up where we left off: ${question}`;
}

import { GoogleGenAI } from "@google/genai";

export const DEFAULT_MODEL = "gemini-3.8-flash";

export class MissingApiKeyError extends Error {
  constructor() {
    super("GEMINI_API_KEY is not set");
  }
}

export function getModelName(): string {
  return process.env.GEMINI_MODEL?.trim() || DEFAULT_MODEL;
}

const globalForAi = globalThis as unknown as { __genai?: { key: string; client: GoogleGenAI } };

/** Server-only Gemini client. Throws MissingApiKeyError if the key isn't configured. */
export function getGenAI(): GoogleGenAI {
  const key = process.env.GEMINI_API_KEY?.trim();
  if (!key) throw new MissingApiKeyError();
  if (globalForAi.__genai?.key !== key) {
    globalForAi.__genai = { key, client: new GoogleGenAI({ apiKey: key }) };
  }
  return globalForAi.__genai.client;
}

import { ApiError } from "@google/genai";
import type { ChatError } from "@/lib/chat/types";
import { getModelName, MissingApiKeyError } from "./client";

/** Maps any thrown error to a user-facing ChatError. */
export function toChatError(err: unknown): ChatError {
  if (err instanceof MissingApiKeyError) {
    return {
      code: "invalid_key",
      error: "The Gemini API key is missing. Add GEMINI_API_KEY to .env and restart the server.",
      retryable: false,
    };
  }

  const status = err instanceof ApiError ? err.status : undefined;
  const text = err instanceof Error ? err.message : String(err);

  if (status === 429 || /RESOURCE_EXHAUSTED|quota/i.test(text)) {
    return {
      code: "rate_limited",
      error: "The free-tier rate limit was reached. Wait about a minute, then try again.",
      retryable: true,
    };
  }
  if (status === 401 || status === 403 || /API key not valid|API_KEY_INVALID|PERMISSION_DENIED/i.test(text)) {
    return {
      code: "invalid_key",
      error: "The Gemini API key was rejected. Check GEMINI_API_KEY in .env and restart the server.",
      retryable: false,
    };
  }
  if (status === 404 || /not found|is not supported/i.test(text)) {
    return {
      code: "model_not_found",
      error: `The model "${getModelName()}" isn't available for this API key. Set GEMINI_MODEL in .env to a model you can use and restart.`,
      retryable: false,
    };
  }
  if (status !== undefined && status >= 500) {
    return { code: "model_error", error: "The model service had a problem. Try again in a moment.", retryable: true };
  }
  if (status === 400) {
    return { code: "bad_request", error: "The model couldn't process that request. Try rephrasing.", retryable: true };
  }
  return { code: "internal", error: "Something went wrong. Try again.", retryable: true };
}

import { z } from "zod";
import { getDestinationInfo } from "@/lib/destinations/getDestinationInfo";
import { getCompleteness, type Completeness } from "@/lib/profile/completeness";
import { updateProfileArgsSchema, type ProfileOp } from "@/lib/profile/ops";
import type { ApplyResult } from "@/lib/profile/reducer";
import type { ToolEvent } from "@/lib/chat/types";
import type { UserProfile } from "@/lib/profile/schema";

/**
 * Makes a Zod-generated JSON Schema friendlier to Gemini's function-calling subset:
 * drops $schema, turns oneOf into anyOf and const into a one-value enum.
 */
export function toGeminiSchema(schema: unknown): unknown {
  if (Array.isArray(schema)) return schema.map(toGeminiSchema);
  if (!schema || typeof schema !== "object") return schema;
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(schema as Record<string, unknown>)) {
    if (key === "$schema") continue;
    if (key === "oneOf") out.anyOf = toGeminiSchema(value);
    else if (key === "const") out.enum = [value];
    else out[key] = toGeminiSchema(value);
  }
  return out;
}

export const FUNCTION_DECLARATIONS = [
  {
    name: "getDestinationInfo",
    description:
      "Get information about a destination: best months, what it's known for, costs, visa rules by passport, dietary and accessibility notes. Returns {found:false} for destinations you have no data on.",
    parametersJsonSchema: {
      type: "object",
      properties: { name: { type: "string", description: "Destination name, e.g. 'Kyoto'." } },
      required: ["name"],
    },
  },
  {
    name: "updateProfile",
    description:
      "Apply one or more changes to the user's travel profile. Returns which ops succeeded, errors for any that failed, and the updated completeness.",
    parametersJsonSchema: toGeminiSchema(z.toJSONSchema(updateProfileArgsSchema)),
  },
];

export interface ToolDeps {
  applyProfileOps: (ops: readonly ProfileOp[]) => ApplyResult;
}

export interface ToolOutcome {
  /** Sent back to the model as the function response. */
  response: Record<string, unknown>;
  /** Shown in the UI as a badge. */
  event: ToolEvent;
  /** Present when the profile changed. */
  profile?: { profile: UserProfile; completeness: Completeness };
}

export function executeTool(name: string, args: unknown, deps: ToolDeps): ToolOutcome {
  if (name === "getDestinationInfo") {
    const parsed = z.object({ name: z.string().min(1) }).safeParse(args);
    if (!parsed.success) {
      return {
        response: { error: "Provide a destination name." },
        event: { name: "getDestinationInfo", found: false },
      };
    }
    const info = getDestinationInfo(parsed.data.name);
    return {
      response: info
        ? { found: true, destination: info }
        : {
            found: false,
            message: `No information about "${parsed.data.name}". Tell the user you don't know anything about it. Do not use outside knowledge about it.`,
          },
      event: { name: "getDestinationInfo", arg: parsed.data.name, found: info !== null },
    };
  }

  if (name === "updateProfile") {
    const parsed = updateProfileArgsSchema.safeParse(args);
    if (!parsed.success) {
      return {
        response: {
          ok: false,
          error: "Invalid arguments",
          issues: parsed.error.issues.slice(0, 5).map((i) => `${i.path.join(".")}: ${i.message}`),
        },
        event: { name: "updateProfile" },
      };
    }
    const result = deps.applyProfileOps(parsed.data.ops);
    const completeness = getCompleteness(result.profile);
    const errors = result.results.flatMap((r, index) => (r.ok ? [] : [{ index, error: r.error }]));
    return {
      response: {
        ok: errors.length === 0,
        applied: result.results.length - errors.length,
        errors,
        completeness: { done: completeness.done, total: completeness.total, missing: completeness.missing },
      },
      event: { name: "updateProfile" },
      profile: result.changed ? { profile: result.profile, completeness } : undefined,
    };
  }

  return { response: { error: `Unknown tool ${name}` }, event: { name: "updateProfile" } };
}

import type { ChatMessage, ProfileSnapshot, ToolEvent } from "@/lib/chat/types";
import { getCompleteness } from "@/lib/profile/completeness";
import type { ProfileOp } from "@/lib/profile/ops";
import type { ApplyResult } from "@/lib/profile/reducer";
import type { UserProfile } from "@/lib/profile/schema";
import { buildSystemPrompt } from "./systemPrompt";
import { executeTool, FUNCTION_DECLARATIONS } from "./tools";

export const MAX_TOOL_ROUNDS = 5;

/** Minimal shapes of the Gemini API we rely on (kept loose so tests can fake them). */
export interface Part {
  text?: string;
  thought?: boolean;
  functionCall?: { id?: string; name?: string; args?: Record<string, unknown> };
  functionResponse?: { id?: string; name?: string; response?: Record<string, unknown> };
  [key: string]: unknown;
}
export interface Content {
  role: "user" | "model";
  parts: Part[];
}
export interface Chunk {
  candidates?: { content?: { parts?: Part[] } }[];
}
export interface GenerateRequest {
  contents: Content[];
  config: {
    systemInstruction: string;
    tools: { functionDeclarations: typeof FUNCTION_DECLARATIONS }[];
    toolConfig?: { functionCallingConfig: { mode: "NONE" | "AUTO" } };
    abortSignal?: AbortSignal;
  };
}
export type GenerateStream = (req: GenerateRequest) => Promise<AsyncIterable<Chunk>>;

export interface AgentDeps {
  generate: GenerateStream;
  loadProfile: () => UserProfile;
  applyProfileOps: (ops: readonly ProfileOp[]) => ApplyResult;
}

export type AgentEvent =
  | { type: "token"; text: string }
  | { type: "tool"; tool: ToolEvent }
  | { type: "profile"; snapshot: ProfileSnapshot };

/** Converts stored chat history to Gemini contents (skips failed replies, merges same-role turns). */
export function toContents(history: readonly ChatMessage[]): Content[] {
  const contents: Content[] = [];
  for (const m of history) {
    if (m.status === "error" || !m.content.trim()) continue;
    const role = m.role === "user" ? "user" : "model";
    const last = contents.at(-1);
    if (last?.role === role) last.parts[0].text = `${last.parts[0].text}\n\n${m.content}`;
    else contents.push({ role, parts: [{ text: m.content }] });
  }
  // The API expects the conversation to start with a user turn.
  if (contents[0]?.role === "model") contents.unshift({ role: "user", parts: [{ text: "(session started)" }] });
  return contents;
}

/**
 * Runs one assistant turn: streams text, executes tool calls, feeds results back,
 * and repeats until the model answers with text only (max MAX_TOOL_ROUNDS tool rounds).
 */
export async function* runAgent(opts: {
  history: readonly ChatMessage[];
  deps: AgentDeps;
  signal?: AbortSignal;
}): AsyncGenerator<AgentEvent> {
  const { deps, signal } = opts;
  const contents = toContents(opts.history);

  for (let round = 0; round <= MAX_TOOL_ROUNDS; round++) {
    const profile = deps.loadProfile();
    const stream = await deps.generate({
      contents,
      config: {
        systemInstruction: buildSystemPrompt(profile, getCompleteness(profile)),
        tools: [{ functionDeclarations: FUNCTION_DECLARATIONS }],
        toolConfig: round === MAX_TOOL_ROUNDS ? { functionCallingConfig: { mode: "NONE" } } : undefined,
        abortSignal: signal,
      },
    });

    const modelParts: Part[] = [];
    const calls: NonNullable<Part["functionCall"]>[] = [];
    for await (const chunk of stream) {
      for (const part of chunk.candidates?.[0]?.content?.parts ?? []) {
        // Keep every part (including thought signatures) to send back verbatim.
        modelParts.push(part);
        if (part.functionCall) calls.push(part.functionCall);
        else if (part.text && !part.thought) yield { type: "token", text: part.text };
      }
    }

    if (calls.length === 0) return;

    contents.push({ role: "model", parts: modelParts });
    const responses: Part[] = [];
    for (const call of calls) {
      const name = call.name ?? "";
      const outcome = executeTool(name, call.args ?? {}, deps);
      yield { type: "tool", tool: outcome.event };
      if (outcome.profile) yield { type: "profile", snapshot: outcome.profile };
      responses.push({ functionResponse: { id: call.id, name, response: outcome.response } });
    }
    contents.push({ role: "user", parts: responses });
  }
}

import { FunctionCallingConfigMode, type GenerateContentParameters } from "@google/genai";
import { getGenAI, getModelName } from "./client";
import type { GenerateStream } from "./runAgent";

/** The real Gemini streaming call used by runAgent. */
export const geminiGenerate: GenerateStream = async ({ contents, config }) => {
  const params = {
    model: getModelName(),
    contents,
    config: {
      systemInstruction: config.systemInstruction,
      tools: config.tools,
      abortSignal: config.abortSignal,
      toolConfig: config.toolConfig
        ? { functionCallingConfig: { mode: FunctionCallingConfigMode[config.toolConfig.functionCallingConfig.mode] } }
        : undefined,
    },
  } as GenerateContentParameters;
  return getGenAI().models.generateContentStream(params);
};

import { chatRequestSchema, type ServerEvent, type ToolEvent } from "@/lib/chat/types";
import { deleteMessage, getLastMessage, insertMessage, listRecentMessages } from "@/lib/db/messageRepo";
import { applyProfileOps, loadProfile } from "@/lib/db/profileRepo";
import { toChatError } from "@/lib/llm/errors";
import { geminiGenerate } from "@/lib/llm/gemini";
import { runAgent } from "@/lib/llm/runAgent";
import { encodeSse } from "@/lib/sse/encode";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const HISTORY_LIMIT = 20;
const EMPTY_REPLY = "Sorry, I didn't catch that. Could you say it another way?";

export async function POST(request: Request) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return Response.json({ error: "Invalid JSON body" }, { status: 400 });
  }
  const parsed = chatRequestSchema.safeParse(body);
  if (!parsed.success) {
    return Response.json({ error: "Invalid request", issues: parsed.error.issues }, { status: 400 });
  }
  const { message, opening, retry } = parsed.data;

  // Persist the turn before streaming so a reload mid-reply keeps the user's message.
  const last = getLastMessage();
  if (retry) {
    if (last?.role === "assistant" && last.status !== "complete") deleteMessage(last.id);
    const now = getLastMessage();
    if (now?.role !== "user" || now.content !== message) insertMessage({ role: "user", content: message });
  } else {
    if (opening && last?.content !== opening) insertMessage({ role: "assistant", content: opening });
    insertMessage({ role: "user", content: message });
  }
  const history = listRecentMessages(HISTORY_LIMIT);

  const encoder = new TextEncoder();
  const stream = new ReadableStream<Uint8Array>({
    async start(controller) {
      const send = <E extends ServerEvent>(event: E["event"], data: E["data"]) => {
        try {
          controller.enqueue(encoder.encode(encodeSse(event, data)));
        } catch {
          // Client disconnected; keep going so the reply is still saved.
        }
      };

      let text = "";
      const tools: ToolEvent[] = [];
      try {
        for await (const ev of runAgent({
          history,
          signal: request.signal,
          deps: { generate: geminiGenerate, loadProfile, applyProfileOps },
        })) {
          if (ev.type === "token") {
            text += ev.text;
            send("token", { text: ev.text });
          } else if (ev.type === "tool") {
            tools.push(ev.tool);
            send("tool", ev.tool);
          } else {
            send("profile", ev.snapshot);
          }
        }
        const saved = insertMessage({ role: "assistant", content: text.trim() || EMPTY_REPLY, tools });
        send("done", { message: saved });
      } catch (err) {
        if (request.signal.aborted) {
          if (text.trim() || tools.length) {
            insertMessage({ role: "assistant", content: text.trim(), tools, status: "interrupted" });
          }
        } else {
          console.error("[chat] agent failed", err);
          const error = toChatError(err);
          const saved = insertMessage({ role: "assistant", content: text.trim(), tools, status: "error" });
          send("error", { ...error, message: saved });
        }
      } finally {
        try {
          controller.close();
        } catch {
          // already closed
        }
      }
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "text/event-stream; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
    },
  });
}

import { applyProfileOps } from "@/lib/db/profileRepo";
import { getCompleteness } from "@/lib/profile/completeness";
import { uiProfileRequestSchema } from "@/lib/profile/ops";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/** UI-initiated profile changes (currently: rejecting items). */
export async function POST(request: Request) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return Response.json({ error: "Invalid JSON body" }, { status: 400 });
  }
  const parsed = uiProfileRequestSchema.safeParse(body);
  if (!parsed.success) {
    return Response.json({ error: "Invalid request", issues: parsed.error.issues }, { status: 400 });
  }

  try {
    const result = applyProfileOps(parsed.data.ops);
    const errors = result.results.flatMap((r) => (r.ok ? [] : [r.error]));
    const payload = { profile: result.profile, completeness: getCompleteness(result.profile), errors };
    return Response.json(payload, { status: result.changed ? 200 : 409 });
  } catch (err) {
    console.error("[profile] update failed", err);
    return Response.json({ error: "Could not update the profile" }, { status: 500 });
  }
}

