const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

const ENUM_LABELS: Record<string, string> = {
  solo: "Solo",
  partner: "Partner",
  friends: "Friends",
  "family-with-kids": "Family with kids",
  "family-adults": "Family (adults)",
