  midRange: "Mid-range",
  luxury: "Luxury",
  relaxed: "Relaxed",
  balanced: "Balanced",
  packed: "Packed",
  hot: "Hot",
  warm: "Warm",
  mild: "Mild",
  cold: "Cold",
  weekend: "Weekend",
  "1-week": "1 week",
  "2-weeks": "2 weeks",
  extended: "Extended",
  hostel: "Hostel",
  "budget-hotel": "Budget hotel",
  boutique: "Boutique",
  "luxury-hotel": "Luxury hotel",
  rental: "Rental",
  resort: "Resort",
  camping: "Camping",
};

/** Human label for an enum value; free text is capitalized. */
export function labelFor(value: string): string {
  return ENUM_LABELS[value] ?? value.charAt(0).toUpperCase() + value.slice(1);
}

const regionNames = new Intl.DisplayNames(["en"], { type: "region" });

export function passportLabel(code: string): string {
  try {
    return regionNames.of(code) ?? code;
  } catch {
    return code;
  }
}

export function homeBaseLabel(hb: HomeBase): string {
  return hb.city ? `${hb.city}, ${hb.country}` : hb.country;
}

/** [3,4,5,9,10,11] -> "Mar–May, Sep–Nov"; wraps across the year end ([11,12,1] -> "Nov–Jan"). */
export function monthRangesLabel(months: readonly number[]): string {
  const sorted = [...new Set(months)].filter((m) => m >= 1 && m <= 12).sort((a, b) => a - b);
  if (sorted.length === 0) return "";
  if (sorted.length === 12) return "Year-round";

  const groups: number[][] = [];
  for (const m of sorted) {
    const last = groups.at(-1);
    if (last && m === last[last.length - 1] + 1) last.push(m);
    else groups.push([m]);
  }
  if (groups.length > 1 && groups[0][0] === 1 && groups.at(-1)!.at(-1) === 12) {
    groups[0] = [...groups.pop()!, ...groups[0]];
  }
  return groups
    .map((g) => (g.length === 1 ? MONTHS[g[0] - 1] : `${MONTHS[g[0] - 1]}–${MONTHS[g[g.length - 1] - 1]}`))
    .join(", ");
}

export function placeLabel(place: Place): string {
  return [place.name, place.status, place.sentiment].filter(Boolean).join(" · ");
}

/**
 * Keys of everything that was added or changed between two profiles:
 * list item ids, place ids, and "field:<path>" for single-value fields.
 */
export function changedKeys(prev: UserProfile, next: UserProfile): string[] {
  const keys: string[] = [];
  for (const section of ["traveler", "preferences"] as const) {
    const before = prev[section] as Record<string, unknown>;
    const after = next[section] as Record<string, unknown>;
    for (const [key, value] of Object.entries(after)) {
      if (Array.isArray(value)) {
        const old = (before[key] as { id: string; value: unknown; source: string }[] | null) ?? [];
        for (const item of value as { id: string; value: unknown; source: string }[]) {
          const match = old.find((o) => o.id === item.id);
          if (!match || match.source !== item.source) keys.push(item.id);
        }
      } else if (value && JSON.stringify(value) !== JSON.stringify(before[key])) {
        keys.push(`field:${section}.${key}`);
      }
    }
  }
  for (const place of next.places) {
    const old = prev.places.find((p) => p.id === place.id);
    if (!old || JSON.stringify(old) !== JSON.stringify(place)) keys.push(place.id);
  }
  return keys;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { ToastData } from "@/components/ui/feedback";

const AUTO_DISMISS_MS = 6000;

export function useToast() {
  const [toast, setToast] = useState<ToastData | null>(null);
  const nextId = useRef(1);

  const show = useCallback((message: string, action?: ToastData["action"]) => {
    setToast({ id: nextId.current++, message, action });
  }, []);
  const dismiss = useCallback(() => setToast(null), []);

  useEffect(() => {
    if (!toast) return;
    const timer = setTimeout(() => setToast((t) => (t?.id === toast.id ? null : t)), AUTO_DISMISS_MS);
    return () => clearTimeout(timer);
  }, [toast]);

  return { toast, show, dismiss };
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { ProfileSnapshot } from "@/lib/chat/types";
import { getCompleteness } from "@/lib/profile/completeness";
import { changedKeys } from "@/lib/profile/format";
import type { RejectOp } from "@/lib/profile/ops";
import { applyOps } from "@/lib/profile/reducer";

const HIGHLIGHT_MS = 3000;

/**
 * Holds the profile shown in the ledger. Server snapshots (from the chat stream)
 * replace it; rejections are applied optimistically and rolled back on failure.
 */
export function useProfile(initial: ProfileSnapshot, onRejectFailed: (label: string, retry: () => void) => void) {
  const [snapshot, setSnapshot] = useState(initial);
  const [highlighted, setHighlighted] = useState<Set<string>>(new Set());
  const current = useRef(snapshot);
  current.current = snapshot;
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);

  const highlight = useCallback((keys: string[]) => {
    if (keys.length === 0) return;
    setHighlighted(new Set(keys));
    clearTimeout(timer.current);
    timer.current = setTimeout(() => setHighlighted(new Set()), HIGHLIGHT_MS);
  }, []);
  useEffect(() => () => clearTimeout(timer.current), []);

  const applyServerSnapshot = useCallback(
    (next: ProfileSnapshot) => {
      highlight(changedKeys(current.current.profile, next.profile));
      setSnapshot(next);
    },
    [highlight],
  );

  const reject = useCallback(
    async (op: RejectOp, label: string) => {
      const before = current.current;
      const optimistic = applyOps(before.profile, [op]);
      if (!optimistic.changed) return;
      setSnapshot({ profile: optimistic.profile, completeness: getCompleteness(optimistic.profile) });

      const retry = () => void reject(op, label);
      try {
        const res = await fetch("/api/profile", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ops: [op] }),
        });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        setSnapshot((await res.json()) as ProfileSnapshot);
      } catch {
        setSnapshot(before);
        onRejectFailed(label, retry);
      }
    },
    [onRejectFailed],
  );

  return { ...snapshot, highlighted, applyServerSnapshot, reject };
}

"use client";

import { useEffect, useRef, type RefObject } from "react";

const NEAR_BOTTOM_PX = 120;

/** Keeps a scroll container pinned to the bottom when content changes, unless the user scrolled up. */
export function useAutoScroll<T extends HTMLElement>(ref: RefObject<T | null>, dependency: unknown) {
  const pinned = useRef(true);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const onScroll = () => {
      pinned.current = el.scrollHeight - el.scrollTop - el.clientHeight < NEAR_BOTTOM_PX;
    };
    el.addEventListener("scroll", onScroll, { passive: true });
    return () => el.removeEventListener("scroll", onScroll);
  }, [ref]);

  useEffect(() => {
    const el = ref.current;
    if (el && pinned.current) el.scrollTop = el.scrollHeight;
  }, [ref, dependency]);
}

"use client";

import { useCallback, useRef, useState } from "react";
import type { ChatError, ChatMessage, ChatRequest, ProfileSnapshot, ServerEvent } from "@/lib/chat/types";
import { createSseParser } from "@/lib/sse/parse";

export interface UiMessage extends ChatMessage {
  streaming?: boolean;
  error?: ChatError;
}

export type ChatStatus = "idle" | "streaming";

const NETWORK_ERROR: ChatError = {
  code: "network",
  error: "Couldn't reach the server. Check that it's running, then try again.",
  retryable: true,
};

const OPENING_ID = "opening";

function localMessage(role: ChatMessage["role"], content: string, id: string = crypto.randomUUID()): UiMessage {
  return { id, role, content, tools: [], status: "complete", createdAt: new Date().toISOString() };
}

/**
 * Chat state and the streaming POST /api/chat lifecycle: send, stop, retry.
 * Profile snapshots from the stream are forwarded to onProfile.
 */
export function useChat(opts: {
  initialMessages: ChatMessage[];
  opening: string;
  onProfile: (snapshot: ProfileSnapshot) => void;
}) {
  const [messages, setMessages] = useState<UiMessage[]>(() => [
    ...opts.initialMessages.map((m): UiMessage =>
      m.status === "error"
        ? { ...m, error: { code: "internal", error: "This reply didn't finish.", retryable: true } }
        : m,
    ),
    localMessage("assistant", opts.opening, OPENING_ID),
  ]);
  const [status, setStatus] = useState<ChatStatus>("idle");

  const abortRef = useRef<AbortController | null>(null);
  const openingPending = useRef(true);
  const onProfileRef = useRef(opts.onProfile);
  onProfileRef.current = opts.onProfile;

  const stream = useCallback(async (body: ChatRequest) => {
    const draftId = `draft-${crypto.randomUUID()}`;
    setMessages((ms) => [...ms, { ...localMessage("assistant", "", draftId), streaming: true }]);
    setStatus("streaming");

    const controller = new AbortController();
    abortRef.current = controller;
    const update = (fn: (m: UiMessage) => UiMessage) =>
      setMessages((ms) => ms.map((m) => (m.id === draftId ? fn(m) : m)));

    let finished = false;
    const fail = (error: ChatError, saved?: ChatMessage) => {
      finished = true;
      update((m) => ({ ...m, ...saved, status: "error", streaming: false, error }));
    };

    try {
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
        signal: controller.signal,
      });
      if (!res.ok || !res.body) {
        fail({ code: "bad_request", error: "The server couldn't accept that message.", retryable: true });
        return;
      }

      const parser = createSseParser(({ event, data }) => {
        const e = { event, data: JSON.parse(data) } as ServerEvent;
        switch (e.event) {
          case "token":
            update((m) => ({ ...m, content: m.content + e.data.text }));
            break;
          case "tool":
            update((m) => ({ ...m, tools: [...m.tools, e.data] }));
            break;
          case "profile":
            onProfileRef.current(e.data);
            break;
          case "done":
            finished = true;
            update(() => ({ ...e.data.message, streaming: false }));
            break;
          case "error": {
            const { message: saved, ...error } = e.data;
            fail(error, saved);
            break;
          }
        }
      });

      const reader = res.body.pipeThrough(new TextDecoderStream()).getReader();
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        parser.push(value);
      }
      parser.flush();
      if (!finished) fail(NETWORK_ERROR);
    } catch {
      if (controller.signal.aborted) {
        setMessages((ms) =>
          ms.flatMap((m) => {
            if (m.id !== draftId) return [m];
            return m.content || m.tools.length ? [{ ...m, streaming: false, status: "interrupted" as const }] : [];
          }),
        );
      } else {
        fail(NETWORK_ERROR);
      }
    } finally {
      abortRef.current = null;
      setStatus("idle");
    }
  }, []);

  const send = useCallback(
    (text: string) => {
      const message = text.trim();
      if (!message || abortRef.current) return;
      const body: ChatRequest = { message };
      if (openingPending.current) {
        body.opening = opts.opening;
        openingPending.current = false;
      }
      setMessages((ms) => [...ms, localMessage("user", message)]);
      void stream(body);
    },
    [opts.opening, stream],
  );

  const retry = useCallback(() => {
    if (abortRef.current) return;
    const lastUser = [...messages].reverse().find((m) => m.role === "user");
    if (!lastUser) return;
    // Drop the failed reply(s) after the last user message.
    setMessages((ms) => {
      const idx = ms.lastIndexOf(lastUser);
      return ms.filter((m, i) => i <= idx || m.status === "complete");
    });
    void stream({ message: lastUser.content, retry: true });
  }, [messages, stream]);

  const stop = useCallback(() => abortRef.current?.abort(), []);

  return { messages, status, send, retry, stop };
}

"use client";

import { useRef, useState, type FormEvent, type KeyboardEvent } from "react";
import type { ChatStatus, UiMessage } from "@/hooks/useChat";
import { useAutoScroll } from "@/hooks/useAutoScroll";
import { Button } from "@/components/ui/Button";
import { Alert } from "@/components/ui/feedback";
import { IconButton } from "@/components/ui/IconButton";
import { RetryIcon, SearchIcon, SendIcon, StopIcon } from "@/components/ui/icons";
import { cx } from "@/components/ui/cx";
import type { ToolEvent } from "@/lib/chat/types";

interface ChatPanelProps {
  messages: UiMessage[];
  status: ChatStatus;
  onSend: (text: string) => void;
  onStop: () => void;
  onRetry: () => void;
}

export function ChatPanel({ messages, status, onSend, onStop, onRetry }: ChatPanelProps) {
  const threadRef = useRef<HTMLDivElement>(null);
  const last = messages.at(-1);
  useAutoScroll(threadRef, `${messages.length}:${last?.content.length}:${last?.tools.length}`);

  return (
    <main className="flex min-w-0 flex-1 flex-col">
      <div ref={threadRef} className="flex-1 overflow-y-auto py-8" aria-live="polite">
        <div className="mx-auto flex w-[720px] flex-col gap-5">
          {messages.map((m) => (
            <MessageItem key={m.id} message={m} isLast={m === last} onRetry={onRetry} />
          ))}
        </div>
      </div>
      <Composer streaming={status === "streaming"} onSend={onSend} onStop={onStop} />
    </main>
  );
}

function MessageItem({ message, isLast, onRetry }: { message: UiMessage; isLast: boolean; onRetry: () => void }) {
  if (message.role === "user") {
    return (
      <div className="flex justify-end">
        <div className="max-w-[520px] rounded-[14px_14px_4px_14px] bg-brand-700 px-4 py-3 whitespace-pre-wrap text-white">
          {message.content}
        </div>
      </div>
    );
  }

  const waiting = message.streaming && !message.content && message.tools.length === 0;
  return (
    <div className="max-w-[620px]">
      <div className="mb-1.5 font-mono text-[11px] font-medium tracking-[0.08em] text-brand-700 uppercase">Assistant</div>
      {message.tools.length > 0 && (
        <div className="mb-2.5 flex flex-wrap gap-2">
          {dedupeTools(message.tools).map((t, i) => (
            <ToolBadge key={i} tool={t} />
          ))}
        </div>
      )}
      {waiting && <span className="text-subtle">Thinking…</span>}
      {message.content && (
        <div className="whitespace-pre-wrap">
          {message.content}
          {message.streaming && (
            <span aria-hidden="true" className="ml-0.5 inline-block h-[17px] w-2 animate-blink bg-accent align-[-3px]" />
          )}
        </div>
      )}
      {message.status === "interrupted" && <div className="mt-1 text-[13px] text-subtle italic">Stopped.</div>}
      {message.error && (
        <Alert
          title="Reply interrupted"
          action={
            isLast && message.error.retryable ? (
              <Button size="sm" onClick={onRetry}>
                <RetryIcon size={14} />
                Retry
              </Button>
            ) : undefined
          }
        >
          {message.error.error}
          {message.error.code !== "invalid_key" && message.error.code !== "model_not_found" && " Nothing in your profile was lost."}
        </Alert>
      )}
    </div>
  );
}

/** Profile updates can happen several times per turn; show one badge for them. */
function dedupeTools(tools: ToolEvent[]): ToolEvent[] {
  const seen = new Set<string>();
  return tools.filter((t) => {
    const key = `${t.name}:${t.arg ?? ""}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function ToolBadge({ tool }: { tool: ToolEvent }) {
  const label =
    tool.name === "getDestinationInfo"
      ? `Looked up ${tool.arg ?? "destination"}${tool.found === false ? " · no data" : ""}`
      : "Updated profile";
  const muted = tool.name === "getDestinationInfo" && tool.found === false;
  return (
    <span
      className={cx(
        "inline-flex items-center gap-2 rounded-full px-2.5 py-0.5 font-mono text-xs",
        muted ? "bg-neutral-chip text-muted" : "bg-pref-bg text-pref-fg",
      )}
    >
      <SearchIcon size={13} />
      {label}
    </span>
  );
}

function Composer({ streaming, onSend, onStop }: { streaming: boolean; onSend: (t: string) => void; onStop: () => void }) {
  const [text, setText] = useState("");

  const submit = (e?: FormEvent) => {
    e?.preventDefault();
    if (streaming || !text.trim()) return;
    onSend(text);
    setText("");
  };
  const onKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) submit(e);
  };

  return (
    <div className="flex flex-none flex-col items-center border-t border-line pt-4 pb-6">
      <form
        onSubmit={submit}
        className={cx(
          "flex w-[720px] items-center gap-2.5 rounded-xl border-[1.5px] py-2 pr-2 pl-4",
          streaming
            ? "border-line-soft bg-surface"
            : "border-field bg-white focus-within:border-brand-700 focus-within:shadow-[0_0_0_4px_var(--color-brand-100)]",
        )}
      >
        <label htmlFor="chat-input" className="sr-only">
          Message
        </label>
        <textarea
          id="chat-input"
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={onKeyDown}
          placeholder={streaming ? "Assistant is replying…" : "Type your answer…"}
          disabled={streaming}
          rows={1}
          maxLength={4000}
          autoFocus
          className="h-11 flex-1 resize-none bg-transparent py-2.5 text-ink outline-none placeholder:text-subtle disabled:text-subtle"
        />
        {streaming ? (
          <Button variant="danger-outline" onClick={onStop}>
            <StopIcon size={14} />
            Stop
          </Button>
        ) : (
          <IconButton type="submit" aria-label="Send message" variant="primary" size="lg" disabled={!text.trim()}>
            <SendIcon />
          </IconButton>
        )}
      </form>
      <div className="mt-2.5 w-[720px] text-xs text-subtle">
        {streaming ? "Profile updates appear on the right as the reply streams." : "Enter to send · Shift+Enter for a new line"}
      </div>
    </div>
  );
}

"use client";

import type { ReactNode } from "react";
import { Chip, type ChipTone } from "@/components/ui/Chip";
import { cx } from "@/components/ui/cx";
import { ESSENTIALS, type Completeness } from "@/lib/profile/completeness";
import { homeBaseLabel, labelFor, monthRangesLabel, passportLabel, placeLabel } from "@/lib/profile/format";
import type { RejectOp } from "@/lib/profile/ops";
import { FIELD_META, isFieldPath, LIST_META, type ValuePath } from "@/lib/profile/paths";
import type { FieldValue, HomeBase, ListItem, UserProfile } from "@/lib/profile/schema";

export type RejectHandler = (op: RejectOp, label: string) => void;

interface SectionDef {
  title: string;
  tone: ChipTone;
  rows: ValuePath[];
  /** Essential keys counted in the header, if any. */
  essentials?: string[];
}

const SECTIONS: SectionDef[] = [
  {
    title: "Constraints · hard",
    tone: "constraint",
    rows: ["traveler.homeBase", "traveler.passports", "traveler.dietaryRestrictions", "traveler.accessibilityNeeds"],
    essentials: ["homeBase", "passports", "dietaryRestrictions", "accessibilityNeeds"],
  },
  {
    title: "Preferences · soft",
    tone: "pref",
    rows: [
      "preferences.companions",
      "preferences.budgetTier",
      "preferences.travelMonths",
      "preferences.pace",
      "preferences.interests",
    ],
    essentials: ["companions", "budgetTier", "travelMonths", "pace", "interests"],
  },
  {
    title: "Optional",
    tone: "optional",
    rows: [
      "preferences.avoid",
      "preferences.dietaryPreferences",
      "preferences.climate",
      "preferences.tripLength",
      "preferences.accommodation",
    ],
  },
];

const SECTION_STYLES: Record<ChipTone, { text: string; border: string; mark: string; count: string }> = {
  constraint: {
    text: "text-constraint-fg",
    border: "border-constraint-mark",
    mark: "bg-constraint-mark",
    count: "bg-constraint-bg text-constraint-fg",
  },
  pref: { text: "text-pref-fg", border: "border-pref-mark", mark: "bg-pref-mark", count: "bg-pref-bg text-pref-fg" },
  optional: {
    text: "text-optional-fg",
    border: "border-optional-mark",
    mark: "bg-optional-mark",
    count: "bg-optional-bg text-optional-fg",
  },
  place: { text: "text-place-fg", border: "border-place-mark", mark: "bg-place-mark", count: "bg-place-bg text-place-fg" },
};

interface ProfilePanelProps {
  profile: UserProfile;
  completeness: Completeness;
  highlighted: Set<string>;
  onReject: RejectHandler;
}

export function ProfilePanel({ profile, completeness, highlighted, onReject }: ProfilePanelProps) {
  const missing = new Set(completeness.missing);

  return (
    <aside aria-label="Travel profile" className="w-[440px] flex-none overflow-y-auto border-l border-line bg-surface px-7 pt-3 pb-6">
      <div className="flex items-center gap-2.5 pt-1.5 text-xs text-muted">
        <span className="inline-flex h-[22px] items-center rounded-md bg-pref-bg px-2 text-pref-fg">stated</span>
        <span className="inline-flex h-[22px] items-center rounded-md border-[1.5px] border-dashed border-inferred-border bg-inferred-bg px-2 text-inferred-fg">
          inferred
        </span>
        <span>✕ removes any item</span>
      </div>

      {SECTIONS.map((section) => {
        const done = section.essentials?.filter((k) => !missing.has(k)).length;
        return (
          <Section
            key={section.title}
            title={section.title}
            tone={section.tone}
            count={section.essentials ? `${done}/${section.essentials.length}` : undefined}
          >
            {section.rows.map((path) => (
              <Row key={path} label={isFieldPath(path) ? FIELD_META[path].label : LIST_META[path].label}>
                <RowValue path={path} profile={profile} tone={section.tone} highlighted={highlighted} onReject={onReject} />
              </Row>
            ))}
          </Section>
        );
      })}

      <Section title="Places" tone="place" count={profile.places.length ? String(profile.places.length) : undefined}>
        <div className="flex flex-wrap gap-1.5 py-2">
          {profile.places.length === 0 ? (
            <Empty>No places yet. Mention trips you&apos;ve taken or want to take.</Empty>
          ) : (
            profile.places.map((place) => {
              const label = placeLabel(place);
              return (
                <Chip
                  key={place.id}
                  tone="place"
                  label={label}
                  inferred={place.source === "inferred"}
                  note={place.destinationId ? undefined : "no data"}
                  highlighted={highlighted.has(place.id)}
                  onRemove={() => onReject({ op: "reject", path: "places", id: place.id }, place.name)}
                  removeLabel={`Remove ${place.name}`}
                />
              );
            })
          )}
        </div>
      </Section>
    </aside>
  );
}

function Section({ title, tone, count, children }: { title: string; tone: ChipTone; count?: string; children: ReactNode }) {
  const s = SECTION_STYLES[tone];
  return (
    <section>
      <h2
        className={cx(
          "flex items-center justify-between border-b-2 pt-4 pb-2 font-mono text-[11px] font-medium tracking-[0.1em] uppercase",
          s.text,
          s.border,
        )}
      >
        <span className="flex items-center">
          <i aria-hidden="true" className={cx("mr-2 inline-block h-2 w-2 rounded-[2px]", s.mark)} />
          {title}
        </span>
        {count && <span className={cx("rounded-full px-2", s.count)}>{count}</span>}
      </h2>
      {children}
    </section>
  );
}

function Row({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="flex items-start justify-between gap-4 border-b border-dashed border-line-soft py-1.5">
      <div className="w-[140px] flex-none pt-1 text-[13px] text-muted">{label}</div>
      <div className="flex flex-1 flex-wrap justify-end gap-1.5">{children}</div>
    </div>
  );
}

function Empty({ children }: { children: ReactNode }) {
  return <span className="pt-1 text-[13px] text-subtle italic">{children}</span>;
}

function fieldLabel(path: ValuePath, value: unknown): string {
  if (path === "traveler.homeBase") return homeBaseLabel(value as HomeBase);
  if (path === "preferences.travelMonths") return monthRangesLabel(value as number[]);
  return labelFor(String(value));
}

function itemLabel(path: ValuePath, value: string): string {
  return path === "traveler.passports" ? passportLabel(value) : labelFor(value);
}

function RowValue({
  path,
  profile,
  tone,
  highlighted,
  onReject,
}: {
  path: ValuePath;
  profile: UserProfile;
  tone: ChipTone;
  highlighted: Set<string>;
  onReject: RejectHandler;
}) {
  if (isFieldPath(path)) {
    const { section, key } = FIELD_META[path];
    const field = (profile[section] as Record<string, unknown>)[key] as FieldValue | null;
    if (!field) return <Empty>Not asked yet</Empty>;
    const label = fieldLabel(path, field.value);
    return (
      <Chip
        tone={tone}
        label={label}
        inferred={field.source === "inferred"}
        highlighted={highlighted.has(`field:${path}`)}
        onRemove={() => onReject({ op: "reject", path }, label)}
        removeLabel={`Remove ${FIELD_META[path].label}: ${label}`}
      />
    );
  }

  const { section, key } = LIST_META[path];
  const items = (profile[section] as Record<string, unknown>)[key] as ListItem[] | null;
  if (items === null) return <Empty>Not asked yet</Empty>;
  if (items.length === 0) return <span className="pt-1 text-[13px] text-ink">None</span>;
  return (
    <>
      {items.map((item) => {
        const label = itemLabel(path, item.value);
        return (
          <Chip
            key={item.id}
            tone={tone}
            label={label}
            inferred={item.source === "inferred"}
            highlighted={highlighted.has(item.id)}
            onRemove={() => onReject({ op: "reject", path, id: item.id }, label)}
            removeLabel={`Remove ${label}`}
          />
        );
      })}
    </>
  );
}

/** Essentials lookup re-exported for the header. */
