/**
 * Makes a Zod-generated JSON Schema friendlier to Gemini's function-calling subset:
 * drops $schema, turns oneOf into anyOf and const into a one-value enum.
 */
export function toGeminiSchema(schema: unknown): unknown {
  if (Array.isArray(schema)) return schema.map(toGeminiSchema);
  if (!schema || typeof schema !== "object") return schema;
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(schema as Record<string, unknown>)) {
    if (key === "$schema") continue;
    if (key === "oneOf") out.anyOf = toGeminiSchema(value);
    else if (key === "const") out.enum = [value];
    else out[key] = toGeminiSchema(value);
  }
  return out;
}

