import { ApiError, FunctionCallingConfigMode, type GenerateContentParameters } from "@google/genai";
import { getGenAI, getModelName } from "./client";
import type { GenerateStream } from "./runAgent";

const RETRY_STATUSES = new Set([500, 502, 503, 504]);
const RETRY_DELAYS_MS = [800, 2000];

const sleep = (ms: number, signal?: AbortSignal) =>
  new Promise<void>((resolve, reject) => {
    const timer = setTimeout(resolve, ms);
    signal?.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(signal.reason);
    });
  });

/**
 * The real Gemini streaming call used by runAgent. Transient 5xx errors that happen
 * before the stream starts (e.g. "model overloaded") are retried with backoff.
 */
export const geminiGenerate: GenerateStream = async ({ contents, config }) => {
  const params = {
    model: getModelName(),
    contents,
    config: {
      systemInstruction: config.systemInstruction,
      tools: config.tools,
      abortSignal: config.abortSignal,
      toolConfig: config.toolConfig
        ? { functionCallingConfig: { mode: FunctionCallingConfigMode[config.toolConfig.functionCallingConfig.mode] } }
        : undefined,
    },
  } as GenerateContentParameters;

  for (let attempt = 0; ; attempt++) {
    try {
      return await getGenAI().models.generateContentStream(params);
    } catch (err) {
      const retryable = err instanceof ApiError && RETRY_STATUSES.has(err.status);
      if (!retryable || attempt >= RETRY_DELAYS_MS.length || config.abortSignal?.aborted) throw err;
      console.warn(`[gemini] ${err.status} on attempt ${attempt + 1}; retrying`, err.message);
      await sleep(RETRY_DELAYS_MS[attempt], config.abortSignal);
    }
  }
};

